//! Source-qualified definitions bind two seeded slots before any lookup.
use super::finalize_simple;
use crate::engine::SymbolicAnswer;
use crate::event_log::EventLog;
use crate::seed::{SourceRecord, localized_response, prompt_patterns, source_registry};
use crate::source_fetch::{CachedSourceClient, SourceTransport};

#[derive(Debug, Clone, PartialEq, Eq)]
pub(super) struct Request {
    pub term: String,
    pub source: String,
    pub language: String,
}
fn matches_source(label: &str, source: &SourceRecord) -> bool {
    [source.id.as_str(), source.name.as_str()].iter().any(|name| name.to_lowercase() == label.to_lowercase())
}
fn unquote(value: &str) -> String {
    let value = value.trim();
    let pairs = [('"', '"'), ('\'', '\''), ('`', '`'), ('«', '»'), ('“', '”'), ('‘', '’')];
    for (first, last) in pairs {
        if value.starts_with(first) && value.ends_with(last) && value.len() >= first.len_utf8() + last.len_utf8() {
            return value[first.len_utf8()..value.len() - last.len_utf8()].trim().to_owned();
        }
    }
    value.to_owned()
}
fn literal_pattern(text: &str) -> String {
    regex::escape(text).replace(' ', "\\s+")
}
pub(super) fn request(prompt: &str) -> Option<Request> {
    let input = prompt.trim().trim_end_matches(['.', '?', '!', '。', '？', '！']).trim();
    let registry = source_registry();
    let mut frames: Vec<_> = prompt_patterns().into_iter().filter(|row| row.intent == "source-qualified-definition" && row.kind == "frame").collect();
    frames.sort_by_key(|row| std::cmp::Reverse(row.text.encode_utf16().count()));
    for frame in frames {
        let term_first = frame.text.find("{term}")? < frame.text.find("{source}")?;
        let (first, second) = if term_first { ("{term}", "{source}") } else { ("{source}", "{term}") };
        let Some((before, tail)) = frame.text.split_once(first) else { continue; };
        let Some((middle, after)) = tail.split_once(second) else { continue; };
        if middle.trim().is_empty() || [before, middle, after].iter().any(|text| text.contains(['{', '}'])) { continue; }
        let Ok(outer) = regex::RegexBuilder::new(&format!("^{}(.*){}$", literal_pattern(before), literal_pattern(after))).case_insensitive(true).build() else { continue; };
        let Some(captures) = outer.captures(input) else { continue; };
        let body = &captures[1];
        let Ok(separator) = regex::RegexBuilder::new(&literal_pattern(middle)).case_insensitive(true).build() else { continue; };
        let mut candidates = Vec::new();
        for boundary in separator.find_iter(body) {
            let left = unquote(&body[..boundary.start()]);
            let right = unquote(&body[boundary.end()..]);
            let (term, source) = if term_first { (left, right) } else { (right, left) };
            if term.is_empty() || source.is_empty() || term.contains(['\n', '\r']) || source.contains(['\n', '\r']) { continue; }
            candidates.push(Request { term, source, language: frame.language.clone() });
        }
        let bound = candidates.iter().filter(|candidate| registry.iter().any(|record| matches_source(&candidate.source, record))).max_by_key(|candidate| candidate.source.len());
        if let Some(bound) = bound { return Some(bound.clone()); }
        if !candidates.is_empty() { return if term_first { candidates.pop() } else { Some(candidates.remove(0)) }; }
    }
    None
}
fn render(intent: &str, language: &str, values: &[(&str, &str)]) -> String {
    let mut output = localized_response(intent, language).unwrap_or_default();
    for (name, value) in values { output = output.replace(&format!("{{{name}}}"), value); }
    output
}
