    log.append("source-qualified-definition:status", status.to_owned());
    let body = render("source-qualified-definition-unresolved", &request.language, &[("term", &request.term), ("source", &request.source), ("status", status)]);
    finalize_simple(prompt, log, "concept_lookup", "response:source-qualified-definition", &body, 0.85)
}
