    if matches.len() > 1 { return Some(unresolved(prompt, log, &request, "ambiguous-source")); }
    let preferences = crate::solver_handler_how_synthesis::service_preferences_from_env(log);
    if !preferences.allows(record) { return Some(unresolved(prompt, log, &request, "disabled-source")); }
