    let ambiguous = record.extractor == "mediawiki_summary_v1" && value.get("type").and_then(serde_json::Value::as_str) == Some("disambiguation");
    let items = if ambiguous {
        crate::how_to_guide::extract::list_items(value.get("extract_html").and_then(serde_json::Value::as_str).unwrap_or_default()).iter().map(|item| {
            crate::how_to_guide::extract::decode_entities(&crate::how_to_guide::extract::strip_html(item)).split_whitespace().collect::<Vec<_>>().join(" ")
        }).filter(|item| !item.is_empty()).collect::<Vec<_>>()
    } else { crate::concept_lookup::extractor_gloss_texts(&record.extractor, capture.bytes(), &request.term) };
